.pbwire_schema_matrix3 <- NULL
.pbwire_init_schema_matrix3 <- function(bytes = .pbwire_desc_matrix3) {
  .pbwire_schema_matrix3 <<- pbwire_load_raw(bytes)
  .pbwire_schema_matrix3
}

.pbwire_use_schema_matrix3 <- function(schema) {
  .pbwire_schema_matrix3 <<- schema
}

.pbwire_get_schema_matrix3 <- function() {
  if (is.null(.pbwire_schema_matrix3)) {
    .pbwire_init_schema_matrix3()
  }
  .pbwire_schema_matrix3
}

# Every message in this file, for whole-schema pre-registration.
.pbwire_message_names_matrix3 <- c(
  "structtest.Inner3",
  "structtest.Scalars3"
)

.pbwire_preload_matrix3 <- function() {
  s <- .pbwire_get_schema_matrix3()
  for (n in .pbwire_message_names_matrix3) {
    pbwire_message(s, n)
  }
  invisible(.pbwire_message_names_matrix3)
}
